NAMES={'girder':'钢梁节段','splice':'全粘结拼接试件','crossframe':'平板杆件横撑','diaphragm':'开孔横隔板','stiffener':'带加劲肋钢梁','deck':'闭口肋桥面板','concrete':'未开裂混凝土梁','bearing':'全粘结叠层支座'} # Label actual modeled idealizations explicitly.
def main(): # Produce a reviewable report and complete non-cache evidence archive.
    output=ROOT/'deliverables';output.mkdir(exist_ok=True);audit=json.loads((RUN/'audit.json').read_text());assert audit['status']=='PASS';calibration=json.loads((RUN/'calibration_evaluation.json').read_text());meshes=json.loads((RUN/'mesh_convergence_final.json').read_text());records=[];all_alternatives=[];native_seconds=[];fit_seconds=[] # Require final scientific and storage audit before packaging.
    for family in FAMILIES: # Summarize every frozen topology model with the same held-out denominator.
        selected=json.loads((RUN/f'selected_{family}.json').read_text());round_id=selected['selected_round'];selected_eval=selected['result']['summary'];initial=json.loads((RUN/f'training_{family}.json').read_text())[0]['summary'];correction=json.loads((RUN/'correction'/family/'correction.json').read_text());meta=json.loads((RUN/'meshes'/f'{family}.json').read_text());mesh=next(v for v in meshes if v['family']==family);cal=next(v for v in calibration if v['family']==family) # Bind all metrics to the actual validation-selected weights.
        alternatives=[v for case in correction['cases'] for v in case['alternatives']];all_alternatives.extend(alternatives);native_seconds.extend(case['native_ccx_seconds'] for case in correction['cases']);warm=[v['setup_seconds_shared']+v['iteration_seconds'] for v in alternatives if v['method']=='neural_warm'];cold=[v['setup_seconds_shared']+v['iteration_seconds'] for v in alternatives if v['method']=='zero_cold'] # Keep setup cost in the comparison rather than reporting only cheap back substitutions.
        for path in (RUN/'training').glob(f'round_*/{family}/history_seed_*.json'): fit_seconds.append(json.loads(path.read_text())['seconds']) # Count actual training cost for all attempts and seeds.
        records.append({'family':family,'name':NAMES[family],'selected_round':round_id,'initial_test_relative':initial['test']['mean_relative_L2'],'selected_test_relative':selected_eval['test']['mean_relative_L2'],'polynomial_test_relative':selected_eval['test']['mean_polynomial_relative'],'raw_max_test_residual':selected_eval['test']['max_full_equilibrium_relative'],'raw_accepted_test_cases':selected_eval['test']['accepted'],'corrected_cases':len(correction['cases']),'corrected_alternatives_pass':sum(v['status']=='PASS' for v in alternatives),'corrected_max_residual':max(v['full_equilibrium_relative'] for v in alternatives),'corrected_max_relative':max(v['relative_L2'] for v in alternatives),'median_warm_total_seconds':float(np.median(warm)),'median_cold_total_seconds':float(np.median(cold)),'calibration_test_geometry_coverage':cal['independent_test_geometry_coverage'],'fine_mesh_peak_change':mesh['final_peak_change'],'coarse_training_peak_bias':mesh['coarse_training_peak_vs_finest'],'source':meta['source'],'assumptions':meta['assumptions']}) # Preserve limitations alongside headline numbers.
    summary={'date':'2026-10-24','timezone':'Asia/Shanghai','families':records,'initial_cases':448,'active_search_candidates':4096,'active_new_cases':32,'independent_calibration_cases':144,'total_dataset_cases':624,'training_members':72,'training_rounds_per_family':3,'test_cases':64,'ood_cases':64,'correction_comparisons':len(all_alternatives),'correction_pass':sum(v['status']=='PASS' for v in all_alternatives),'correction_max_residual':max(v['full_equilibrium_relative'] for v in all_alternatives),'correction_max_relative':max(v['relative_L2'] for v in all_alternatives),'training_wall_seconds_sum':float(sum(fit_seconds)),'native_test_seconds_median':float(np.median(native_seconds)),'engineering_release':'HOLD','raw_neural_release':'HOLD: full discrete equilibrium gates fail','achieved_scope':'eight declared research local solid models; linear elastic graph-reduced operators with two objective-driven feedback rounds and independently checked full-FEM fallback','not_completed':['full project-detail reconstruction','global-to-local boundary transfer from a real bridge','universal variable-topology full-order PI-HGNO','material/contact nonlinear operator training','dynamic/time-autoregressive operator training','calibrated bridge safety limit-state and reliability assessment'],'source_base_commit':'0f5e77e063fe703cabe93305177202ad7fcbd63f','audit_status':audit['status']} # State actual bounded experiment completion without claiming the whole MD specification is implemented.
    write_json(RUN/'summary.json',summary) # Save machine-readable final result.
    import matplotlib # Use standard scientific plotting for measured numerical comparisons.
    matplotlib.use('Agg');import matplotlib.pyplot as plt # Render deterministic scientific charts without synthetic engineering fields.
    fig,ax=plt.subplots(figsize=(13,5));x=np.arange(len(records));ax.bar(x-.25,[r['initial_test_relative']*100 for r in records],width=.25,label='Initial graph operator');ax.bar(x,[r['selected_test_relative']*100 for r in records],width=.25,label='Validation-selected graph operator');ax.bar(x+.25,[r['polynomial_test_relative']*100 for r in records],width=.25,label='Polynomial-only ablation') # Compare actual same-test-denominator response errors.
    ax.set_xticks(x,FAMILIES);ax.set_ylabel('Held-out geometry mean displacement L2 error (%)');ax.set_title('64 independent test cases; 8 per local model family');ax.legend(frameon=False);ax.spines[['top','right']].set_visible(False);ax.grid(axis='y',alpha=.2);fig.tight_layout();fig.savefig(output/'local_model_test_errors.png',dpi=200);plt.close(fig) # Save readable source-derived scientific results plot.
