    table=''.join('<tr>'+''.join('<td>'+value+'</td>' for value in [r['name'],str(r['selected_round']),f"{100*r['initial_test_relative']:.2f}%",f"{100*r['selected_test_relative']:.2f}%",f"{100*r['polynomial_test_relative']:.2f}%",f"{r['raw_max_test_residual']:.3g}",f"{r['corrected_max_residual']:.3g}"] )+'</tr>' for r in records) # Present exact parallel comparison metrics.
    mesh_table=''.join('<tr>'+''.join('<td>'+v+'</td>' for v in [r['name'],f"{100*r['fine_mesh_peak_change']:.2f}%",f"{100*r['coarse_training_peak_bias']:.2f}%",f"{100*r['calibration_test_geometry_coverage']:.0f}%",f"{r['median_warm_total_seconds']:.4f}",f"{r['median_cold_total_seconds']:.4f}"])+'</tr>' for r in records) # Include mesh uncertainty, interval coverage and full correction cost.
    assumptions=''.join('<details><summary>'+r['name']+' · '+html.escape(r['source'])+'</summary><ul>'+''.join('<li>'+html.escape(v)+'</li>' for v in r['assumptions'])+'</ul></details>' for r in records) # Make every source-derived versus assumed modeling choice reviewable.
    content='<h1>八类桥梁局部模型：计算、训练、搜索与独立测试</h1><p>2026-10-24 · 本轮已经实际执行完整的局部静力实验流程。工程发布保持 HOLD。</p><p><strong>624 个数据工况、72 组训练权重、4096 个搜索候选、32 个主动补算工况。</strong>另完成 24 个加密网格计算、8 个几何非线性探查及原始证据重放。624 个数据工况包含 448 个初始工况、32 个主动补算与 144 个独立校准工况，不能重复相加计数。</p><h2>得到的结果</h2><p>按验证集选出的原始神经预测，8 类平均测试位移误差为 1.88%–13.07%。完整自由节点平衡残差未通过，因此原始代理不发布。128 个测试及域外工况各执行神经初值、零初值、降阶初值三种完整有限元校正，共 384 个对照全部通过原定 1e-7 平衡残差及 1e-5 参考场误差门槛。校正需要完整矩阵分解，其准确性不能归功于神经网络。</p><table><tr><th>模型</th><th>选中轮次</th><th>初始测试误差</th><th>选中模型误差</th><th>仅多项式误差</th><th>原始最大残差比</th><th>校正后最大残差比</th></tr>'+table+'</table>'+embed(output/'local_model_test_errors.png')+'<h2>网格与独立校准</h2><p>各模型最后两个不同网格的最大位移变化均低于 5%。但钢梁、加劲钢梁、支座的粗训练网格峰值分别仍与最细参考网格存在约 31%、31%、10% 差异，未把细网格验证偷换成粗标签已达工程精度。以下网格结论只对应参考几何，未证明整个参数域网格无关。</p><p>区间校准使用模型选定后新计算的 72 个几何，每个两种荷载；每类 9 个几何建立名义 90% 的组级区间。固定测试采用 Sobol 设计，且样本很少，实际组覆盖率为 50%–100%；因此不宣称理论覆盖保证。64 个域外工况按已登记参数域拒绝独立神经预测。图节点重编号试验通过。</p><table><tr><th>模型</th><th>最后细网格峰值变化</th><th>粗训练网格峰值偏差</th><th>测试几何区间覆盖</th><th>神经初值校正总秒</th><th>零初值校正总秒</th></tr>'+mesh_table+'</table><h2>实际模型与图纸对应</h2><p>这 8 类是标准图纸启发、明确登记假设的局部研究模型，均为 C3D10 二次四面体实体。它们不是 8 座实际桥梁，也不是原图所有细节的完整复建。弹性常数、局部边界和缺失尺寸均保留在 meshes/*.json 与原生输入文件。拼接没有摩擦滑移和预紧力；混凝土没有配筋、预应力与开裂；支座采用线弹性橡胶假设。</p>'+assumptions+embed(RUN/'post/figures/eight_local_models.png')+'<h2>原生应力结果</h2><p>以下为 CalculiX 原始 FRD 的节点外推/平均 von Mises 应力，单位 MPa，最终静力帧，未变形几何，逐模型全值域。位移图单位 mm。云图不是独立的模型有效性证明，也不构成强度、疲劳或安全判定；应力峰值尚未做网格收敛。</p>'+embed(RUN/'post/figures/eight_local_stresses.png')+'<h2>与原 MD 的落实关系</h2><p>A：完成源图登记、八类局部实体、参数域、448 个初始工况、两轮目标驱动搜索、收敛与独立刚度核对。B：实际实现异构粗化图消息传递＋全局交互＋仅训练集构建的 POD 解码；每类固定细网格，共 3 个独立成员及 3 轮模型，包含投影平衡损失和多项式消融。C：完成按几何隔离测试、完整平衡残差、独立区间校准、已知域拒绝、修正成本、版本记录与失败保持。</p><p><strong>尚未完成的原 MD 内容：</strong>真实整桥至局部的边界映射、所有图纸细节复建、任意拓扑全阶 PI-HGNO、接触/材料非线性与动力自回归训练、具备项目依据的安全极限状态及可靠度评价。本轮不能表述为整套桥梁群体系已经验收通过。</p><h2>修复与证据</h2><p>修复了表面荷载的网格一致性、默认静力增量警告、重复网格误判、过严的缩放迭代停止准则与少量写出不完整的结果文件。物理验收阈值保持不变。坏文件、旧回执、重放输入和差异记录均保留；624 个最终数据工况的原生输入、DAT、FRD 哈希及数值档案完整性审查通过。应力/位移全场来自真实有限元结果。</p><h2>文件使用</h2><p>数据包含原生 INP/DAT/FRD、完整位移场、72 组权重、逐轮日志、所有候选评分、细网格与非线性探查、校准记录、物理校正和云图。可再生 stiffness.npz 缓存未放入数据包；按 GitHub 同目录 rebuild_matrices.py 从已保存的网格、材料和载荷恢复，恢复过程再次检查平衡。源码单独提交到 GitHub 分支。原始 44 个图纸文件沿用上一份交付包。</p>' # Build self-contained substantive outcome report.
    report='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>局部模型完整实验记录</title><style>body{font:16px/1.7 sans-serif;color:#152b3e;max-width:1250px;margin:32px auto;padding:0 20px}h1,h2{line-height:1.3}table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:9px;border:1px solid #c7d1dc;text-align:left}th{background:#eaf0f5}img{max-width:100%;height:auto}details{padding:10px;border-bottom:1px solid #dce2e8}summary{cursor:pointer;font-weight:bold}</style>'+content+'</html>' # Provide mobile-readable standalone engineering report.
    (output/'local_models_execution_report.html').write_text(report,encoding='utf-8');shutil.copy2(RUN/'post/figures/eight_local_models.png',output/'eight_local_models.png') # Save final report and readable standalone model image.
    archive_path=output/'local_models_training_evidence.zip';excluded=[];included=[] # Package actual data separately from GitHub-backed source.
    with zipfile.ZipFile(archive_path,'w',zipfile.ZIP_DEFLATED,compresslevel=4) as archive: # Preserve native evidence and learned weights in one downloadable archive.
        for path in sorted(RUN.rglob('*')): # Include all scientific data and historical failures.
            if not path.is_file(): continue # Ignore directories and unavailable filesystem objects.
            if path.name=='stiffness.npz' or path.suffix in ['.cvg','.12d'] or '__pycache__' in path.parts: excluded.append(str(path.relative_to(RUN)));continue # Omit only deterministic matrix caches and redundant solver progress sidecars.
            relative=str(path.relative_to(RUN));archive.write(path,relative);included.append({'path':relative,'bytes':path.stat().st_size,'sha256':sha(path)}) # Bind every included artifact to exact bytes.
        archive.writestr('ARCHIVE_MANIFEST.json',json.dumps({'files':included,'excluded_reproducible_caches':excluded,'code_repository':'https://github.com/Hiram-test/model/tree/codex/local-bridge-operator-20261024','rebuild':'automation/local_bridge_operator/rebuild_matrices.py','units':'N-mm-MPa'},ensure_ascii=False,indent=2)) # Explain completeness and matrix regeneration without hidden missing dependencies.
    with zipfile.ZipFile(archive_path) as archive: assert archive.testzip() is None # Verify complete archive integrity before delivery.
    write_json(output/'local_models_delivery.json',{'archive':str(archive_path),'bytes':archive_path.stat().st_size,'sha256':sha(archive_path),'files':len(included),'report':str(output/'local_models_execution_report.html'),'summary':summary}) # Save precise delivery identities and measured results.
    print(json.dumps({'archive_bytes':archive_path.stat().st_size,'files':len(included),'correction_pass':summary['correction_pass'],'cases':624}),flush=True) # Report finished verified deliverables.
